---此脚本是下拉框的控制组件
require("Game.Common.PopupList.PopupListItem")
PopupListCommon = class("PopupListCommon")

function PopupListCommon:ctor()
end

function PopupListCommon:InitPanel(gameObject)
    self.gameObject = gameObject;
    self.transform = gameObject.transform;
    self:FindComponent(self.transform);
    EventDelegate.Add(self.btn_select.onClick,EventDelegate.Callback(function() self:ButtonSelectOnClick() end));
    EventDelegate.Add(self.btn_close.onClick,EventDelegate.Callback(function() self:CloseOnClick() end));

    self.usedItemList = {};
    self.recycledItemList = {};
    self.selectId = 0;
end

function PopupListCommon:ButtonSelectOnClick()
    if self.selectId ~= 0 then
        self:PlayOpenAnim();
    end
end

function PopupListCommon:FindComponent(transform)
    local tTransform = transform;
    self.lab_select = Util.FindChildEx(tTransform,"btn_select/text"):GetComponent("UILabel");
    self.btn_select = Util.FindChildEx(tTransform,"btn_select/pic1"):GetComponent("UIButton");
    self.btn_close = Util.FindChildEx(tTransform,"btn_close/pic1"):GetComponent("UIEventTrigger");

    self.tweenRoot = Util.FindChildEx(tTransform,"TweenRoot");
    self.itemList = Util.FindChildEx(tTransform,"TweenRoot/ItemList"):GetComponent("UIGrid");
    self.recovery = Util.FindChildEx(tTransform,"recovery");
    self.obj_item = Util.FindChildEx(tTransform,"recovery/Item").gameObject;
end

---显示组件;同时刷新数据，必须调用
function PopupListCommon:Show(show, data)
    if show then
        if data[1] ~= nil then
            self:SetSelectItem(data[1].id, data[1].name)
        end
        self:SetItemList(data);
        self.btn_close:SetActive(false);
    end
    self.gameObject:SetActive(show);
end

---生成Item
function PopupListCommon:SetItemList(data)
    PrefabTool.AdjustPrefabItemCount(#data, self.recovery, self.itemList.transform,
            self.usedItemList, self.recycledItemList, self.obj_item, PopupListItem);
    for i = 1, #self.usedItemList do
        self.usedItemList[i].callback = function(item) self:ItemOnClick(item) end
        self.usedItemList[i]:SetItemInfo(data[i]);
    end
    self.itemList:Reposition();
end

function PopupListCommon:ItemOnClick(item)
    self:SetSelectItem(item.id, item.name);
    self:PlayCloseAnim();
end

function PopupListCommon:SetSelectItem(id, name)
    self.selectId = id;
    self.lab_select.text = name;
end

function PopupListCommon:CloseOnClick()
    self:PlayCloseAnim();
end

function PopupListCommon:PlayOpenAnim()
    local animSequence = DG.Tweening.DOTween.Sequence();
    animSequence:Append(self.tweenRoot:DOScale(Vector3.New(1,0,1),0.3));
    self.btn_close:SetActive(true);
end

function PopupListCommon:PlayCloseAnim()
    local animSequence = DG.Tweening.DOTween.Sequence();
    animSequence:Append(self.tweenRoot:DOScale(Vector3.New(1,1,1),0.3));
    self.btn_close:SetActive(false);
end

